import http from 'k6/http';
import { check, sleep } from 'k6';
export const options = {
  stages: [
    { duration: '2m', target: 200 },   // 200 동시 사용자까지 서서히
    { duration: '5m', target: 200 },   // 유지
    { duration: '2m', target: 0 },     // 감소
  ],
};
export default function () {
  const res = http.get('https://staging/api/search?q=abc');
  check(res, { 'status 200': (r) => r.status === 200 });  // 오류율
  sleep(1);
}
// 결과: RPS, p50/p95/p99, 오류율 을 함께 본다
